{
  "measurement_needs": [
    "Rheological behavior of the polymer as a function of temperature and shear rate",
    "Thermal stability, degradation temperature, and composition of the polymer"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ21",
      "role": "primary",
      "technique": "Rotational and oscillatory rheometry",
      "why": "This hybrid rheometer includes an Environmental Test Chamber, allowing you to measure melt viscosity, shear-thinning behavior, and viscoelastic properties across the elevated temperatures relevant to your extrusion process.",
      "accessories_to_confirm": [
        "Parallel plate or cone-and-plate geometries suitable for polymer melts"
      ]
    },
    {
      "instrument_id": "EQ17",
      "role": "supplementary",
      "technique": "Thermogravimetric Analysis (TGA)",
      "why": "TGA measures sample mass loss as a function of temperature, helping you determine if thermal degradation, crosslinking, or volatilization is occurring at your extrusion temperatures.",
      "accessories_to_confirm": [
        "Standard platinum sample pans and purge gas selection (e.g., nitrogen or air)"
      ]
    },
    {
      "instrument_id": "EQ18",
      "role": "supplementary",
      "technique": "Differential Scanning Calorimetry (DSC)",
      "why": "DSC can identify thermal transitions such as melting points, glass transition temperatures, or premature curing/crosslinking that could cause unexpected viscosity increases during heating.",
      "accessories_to_confirm": [
        "Tzero aluminum pans and hermetic lids"
      ]
    }
  ],
  "not_available": [],
  "clarifying_question": null,
  "summary": "To understand why your polymer remains unexpectedly viscous, you need to characterize its flow properties and thermal profile. The hybrid rheometer (EQ21) can directly measure melt viscosity across your extrusion temperatures using its environmental chamber. Additionally, TGA (EQ17) and DSC (EQ18) can provide supplementary insights into thermal stability and phase transitions."
}

{
  "measurement_needs": [
    "viscosity vs. shear rate",
    "viscosity vs. temperature",
    "molecular weight distribution",
    "thermal stability"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ21",
      "role": "primary",
      "technique_id": "rotational_rheometry",
      "property_id": "viscosity_vs_shear_rate",
      "technique": "Rotational rheometry",
      "why": "It can directly measure the viscosity of your polymer as a function of both shear rate and temperature to help diagnose unexpected high-temperature viscosity.",
      "accessories_to_confirm": [
        "Parallel plate or cone-and-plate measuring geometries",
        "Temperature-control accessory"
      ]
    },
    {
      "instrument_id": "EQ17",
      "role": "supplementary",
      "technique_id": "thermogravimetric_analysis",
      "property_id": "thermal_stability",
      "technique": "Thermogravimetric analysis (TGA)",
      "why": "It checks if your polymer is undergoing thermal degradation, crosslinking, or retaining volatiles at elevated temperatures, which could explain unexpected viscosity increases.",
      "accessories_to_confirm": [
        "Sample pans (ceramic or platinum)",
        "Purge gas supply (nitrogen and air)"
      ]
    }
  ],
  "not_available": [
    {
      "technique_id": "capillary_rheometry",
      "technique": "Capillary rheometry",
      "why_useful": "Extrusion occurs at very high shear rates that exceed the limits of rotational rheometers; a capillary rheometer directly measures processing-shear viscosity."
    },
    {
      "technique_id": "gel_permeation_chromatography",
      "technique": "Gel permeation / size-exclusion chromatography (GPC/SEC)",
      "why_useful": "It determines molecular weight and polydispersity, which strongly influence polymer melt viscosity."
    }
  ],
  "clarifying_question": null,
  "summary": "To understand why your polymer is unexpectedly viscous during extrusion, you should measure its rheological properties across relevant shear rates and temperatures using a rotational rheometer, and check for thermal degradation or crosslinking using a thermogravimetric analyzer. Note that high-shear extrusion viscosities are best evaluated via capillary rheometry, and molecular weight distribution via GPC, neither of which are available on the listed instruments."
}

